def zone_fees(areas_km: dict[str, float]) -> dict[str, int]:
    """For each area and its distance in km, return delivery fee in shillings, or -1 if not served."""
    fees = {}
    for area, km in areas_km.items():
        distance_m = int(km * 1000)
        fee = delivery_fee_kes(distance_m)
        zone = zone_of(area)
        if zone == "X":
            fees[area] = -1
        else:
            fees[area] = fee
    return fees
```

